 "<b style=\"font-size:24px;color:#2a7fb5\">Docentes</b><br><span style=\"font-size:20px;color:#14293a\">Enseñan en el colegio.</span>": "<b style=\"font-size:24px;color:#2a7fb5\">Docents</b><br><span style=\"font-size:20px;color:#14293a\">Ensenyen a l'escola.</span>",
