 "<b style=\"font-size:26px;color:#ca7334\">Respetar el descanso</b><br><span style=\"font-size:21px;color:#14293a\">No hacer ruido de noche.</span>": "<b style=\"font-size:26px;color:#ca7334\">Respectar el descans</b><br><span style=\"font-size:21px;color:#14293a\">No fer soroll de nit.</span>",
 "<b style=\"font-size:26px;color:#33a176\">Saludar y ayudar</b><br><span style=\"font-size:21px;color:#14293a\">Un buen vecino se nota.</span>": "<b style=\"font-size:26px;color:#33a176\">Saludar i ajudar</b><br><span style=\"font-size:21px;color:#14293a\">Un bon veí es nota.</span>",
