 "<b style=\"font-size:26px;color:#bb8222\">Reutilizar</b><br><span style=\"font-size:21px;color:#143325\">Darle otra vida a las cosas.</span>": "<b style=\"font-size:26px;color:#bb8222\">Reutilitzar</b><br><span style=\"font-size:21px;color:#143325\">Donar-li una altra vida a les coses.</span>",
