 "<b style=\"font-size:24px;color:#2e9b73\">Constante</b><br><span style=\"font-size:20px;color:#13203a\">Se queda en el mismo valor.</span>": "<b style=\"font-size:24px;color:#2e9b73\">Constant</b><br><span style=\"font-size:20px;color:#13203a\">Es queda en el mateix valor.</span>",
 "<b style=\"font-size:24px;color:#9a5fc9\">Máximo</b><br><span style=\"font-size:20px;color:#13203a\">El punto más alto.</span>": "<b style=\"font-size:24px;color:#9a5fc9\">Màxim</b><br><span style=\"font-size:20px;color:#13203a\">El punt més alt.</span>",
 "<b style=\"font-size:24px;color:#2f67d3\">Mínimo</b><br><span style=\"font-size:20px;color:#13203a\">El punto más bajo.</span>": "<b style=\"font-size:24px;color:#2f67d3\">Mínim</b><br><span style=\"font-size:20px;color:#13203a\">El punt més baix.</span>",
